function familyDialog(id){const form=$('#family-form');form.reset();form.querySelector('.form-error').hidden=true;form.elements.id.value='';form.elements.revision.value='';delete form.dataset.nicheEvaluationId;const f=state.families.find(f=>f.id===id);$('#family-heading').textContent=f?'Edit channel family':'Create a channel family';if(f){for(const key of ['id','revision','name','tier','audience','niche','timezone','cadence','format'])form.elements[key].value=f[key];form.elements.primaryLocale.value=f.locales[0];form.elements.additionalLocales.value=f.locales.slice(1).join(', ');form.elements.countries.value=f.countries.join(', ');form.elements.monthlyBudget.value=f.budgetCents/100;form.elements.monthlyTokenLimit.value=f.tokenBudget.monthlyLimit;form.elements.scriptTokenLimit.value=f.tokenBudget.scriptJobLimit;form.elements.researchTokenLimit.value=f.tokenBudget.researchJobLimit;form.elements.competitors.value=(f.competitors||[]).map(item=>item.url).join(String.fromCharCode(10));const voice=f.writingVoice||{},nl=String.fromCharCode(10);form.elements.wvAudience.value=voice.audiencePerson||'';form.elements.wvNever.value=(voice.neverWords||[]).join(nl);form.elements.wvOwn.value=(voice.ownPhrases||[]).join(nl);form.elements.wvRefused.value=(voice.refusedClaims||[]).join(nl);form.elements.wvFormat.value=voice.formatNotes||'';form.querySelector('.writing-voice').open=!!f.writingVoice;}$('#family-dialog').showModal();}
function sourceField(source={}){const el=document.createElement('div');el.className='source-field';el.innerHTML=`<div class="source-heading"><strong>Source evidence</strong><button type="button" class="button text-button danger" data-remove-source>Remove</button></div><div class="form-grid"><label>Source title<input data-source="title" required minlength="2" maxlength="200" value="${esc(source.title)}"></label><label>Permission review<select data-source="permission"><option value="unreviewed">Not reviewed</option><option value="permitted" ${source.permission==='permitted'?'selected':''}>I verified permitted use</option></select></label><label class="full">Source URL<input data-source="url" type="url" required maxlength="2000" placeholder="https://…" value="${esc(source.url)}"></label><label class="full">What it supports and why you may use it<textarea data-source="notes" maxlength="3000" rows="2">${esc(source.notes)}</textarea></label></div>`;$('#source-fields').append(el);}
function contentDialog(id){const families=activeFamilies();if(!families.length){toast('Create or restore a family first.');return familyDialog();}const form=$('#content-form');form.reset();form.querySelector('.form-error').hidden=true;form.elements.id.value='';form.elements.revision.value='';$('#source-fields').replaceChildren();form.elements.familyId.innerHTML=families.map(f=>`<option value="${f.id}">${esc(f.name)}</option>`).join('');form.elements.familyId.disabled=false;if(familyFilter)form.elements.familyId.value=familyFilter;const c=state.contents.find(c=>c.id===id);$('#content-heading').textContent=c?'Review or edit draft':'New content draft';$('#revision-warning').textContent=c?'Saving a revision returns this to Draft and clears its approval and storyboard. Close without saving to retain the current version.':'You can save incomplete drafts. Required checks must pass before review.';if(c){for(const key of ['id','revision','familyId','kind','title','angle','hook','script'])form.elements[key].value=c[key];form.elements.targetMinutes.value=c.targetMinutes??'';form.elements.familyId.disabled=true;form.elements.rightsConfirmed.checked=c.rightsConfirmed;c.sources.forEach(sourceField);}$('#content-dialog').showModal();}
function evidenceDialog(id){const families=activeFamilies();if(!families.length){toast('Create a family first.',true);return;}const form=$('#evidence-form');form.reset();form.querySelector('.form-error').hidden=true;form.elements.familyId.innerHTML=families.map(item=>`<option value="${item.id}">${esc(item.name)}</option>`).join('');form.elements.familyId.value=researchFamily||families[0].id;form.elements.expiresAt.value=new Date(Date.now()+30*86400000).toISOString().slice(0,10);const item=state.researchEvidence.find(record=>record.id===id);$('#evidence-heading').textContent=item?'Edit research evidence':'Add research evidence';if(item){for(const field of ['id','revision','familyId','publisher','title','url','publishedAt','accessedAt','expiresAt','permission','analysisMode','notes','rightsNotes'])form.elements[field].value=item[field]??'';form.elements.familyId.disabled=true;}else{form.elements.id.value='';form.elements.revision.value='';form.elements.familyId.disabled=false;}$('#evidence-dialog').showModal();}
async function saveForm(form,save,successMessage){const submit=form.querySelector('[type=submit]'),error=form.querySelector('.form-error');submit.disabled=true;error.hidden=true;try{await save();form.closest('dialog').close();await refresh();toast((typeof successMessage==='function'?successMessage():successMessage)||'Saved to your local workspace.');}catch(e){error.textContent=e.message;error.hidden=false;}finally{submit.disabled=false;}}
$('#family-form').addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;saveForm(form,async()=>{const data=Object.fromEntries(new FormData(form));data.countries=data.countries.split(',').map(x=>x.trim()).filter(Boolean);data.locales=[data.primaryLocale,...data.additionalLocales.split(/[\s,]+/).map(x=>x.trim()).filter(Boolean)];delete data.primaryLocale;delete data.additionalLocales;data.competitors=data.competitors.split(/[\s,]+/).map(x=>x.trim()).filter(Boolean);const lines=value=>String(value||'').split(/[\n,]+/).map(x=>x.trim()).filter(Boolean);data.writingVoice={audiencePerson:data.wvAudience.trim(),neverWords:lines(data.wvNever),ownPhrases:String(data.wvOwn||'').split(/\n+/).map(x=>x.trim()).filter(Boolean),refusedClaims:String(data.wvRefused||'').split(/\n+/).map(x=>x.trim()).filter(Boolean),formatNotes:data.wvFormat.trim()};for(const key of ['wvAudience','wvNever','wvOwn','wvRefused','wvFormat'])delete data[key];data.monthlyBudget=Number(data.monthlyBudget);for(const field of ['cadence','monthlyTokenLimit','scriptTokenLimit','researchTokenLimit'])data[field]=Number(data[field]);data.revision=Number(data.revision);const saved=await api(data.id?`/api/families/${data.id}`:'/api/families',data,data.id?'PUT':'POST');if(!data.id){openFamily=saved.id;returnFamily='';styleAfterCreate=saved.id;location.hash='family';}const nicheEvaluationId=form.dataset.nicheEvaluationId;if(nicheEvaluationId&&!data.id){delete form.dataset.nicheEvaluationId;try{await api(`/api/niche-evaluations/${nicheEvaluationId}/link-family`,{familyId:saved.id});}catch(error){setTimeout(()=>toast(`Family saved, but it could not be linked to the niche: ${error.message}`,true),1200);}}});});
$('#content-form').addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;saveForm(form,async()=>{const data=Object.fromEntries(new FormData(form));data.familyId=form.elements.familyId.value;data.revision=Number(data.revision);data.rightsConfirmed=form.elements.rightsConfirmed.checked;data.targetMinutes=data.targetMinutes?Number(data.targetMinutes):null;data.sources=[...document.querySelectorAll('.source-field')].map(el=>Object.fromEntries([...el.querySelectorAll('[data-source]')].map(input=>[input.dataset.source,input.value])));await api(data.id?`/api/content/${data.id}`:'/api/content',data,data.id?'PUT':'POST');});});
$('#evidence-form').addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;saveForm(form,async()=>{const data=Object.fromEntries(new FormData(form));data.familyId=form.elements.familyId.value;data.revision=Number(data.revision);await api(data.id?`/api/research/evidence/${data.id}`:'/api/research/evidence',data,data.id?'PUT':'POST');});});
$('#voice-profile-form').elements.connectorId.addEventListener('change',event=>{const connector=state.connectors.find(item=>item.id===event.target.value),form=event.target.form;if(!connector)return;form.elements.provider.value=connector.provider;form.elements.model.value=connector.provider==='openai'?'gpt-4o-mini-tts':'eleven_multilingual_v2';});
$('#voice-profile-form').addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;saveForm(form,async()=>{const connector=state.connectors.find(item=>item.id===form.elements.connectorId.value);if(!connector)throw new Error('Choose a current tested voice connector.');const lexicon=form.elements.lexicon.value.split(String.fromCharCode(10)).map(line=>line.replace(String.fromCharCode(13),'').trim()).filter(Boolean).map(line=>{const [pair,notes='']=line.split('|'),parts=pair.split('=>');if(parts.length!==2||!parts[0].trim()||!parts[1].trim())throw new Error('Use “term => replacement | optional note” for each pronunciation entry.');return {term:parts[0].trim(),replacement:parts[1].trim(),notes:notes.trim()};});const data=Object.fromEntries(new FormData(form));for(const key of ['revision','familyRevision','pace','energy','pauseScale','emphasis','stability','similarity','style','monthlyCharacterLimit','maxCharactersPerAudition','priceCentsPerMillionCharacters'])data[key]=Number(data[key]);data.connectorId=connector.id;data.connectorRevision=connector.revision;data.provider=connector.provider;data.consentConfirmed=form.elements.consentConfirmed.checked;data.commercialUseConfirmed=form.elements.commercialUseConfirmed.checked;data.lexicon=lexicon;await api(`/api/families/${data.familyId}/voice-profiles`,data);});});
$('#voice-approval-form').addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;saveForm(form,()=>api(`/api/voice-auditions/${form.elements.auditionId.value}/select`,{approvedBy:form.elements.approvedBy.value,comparisonNotes:form.elements.comparisonNotes.value,intelligibilityConfirmed:form.elements.intelligibilityConfirmed.checked}));});
$('#voice-revoke-form').addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;saveForm(form,()=>api(`/api/voice-approvals/${form.elements.approvalId.value}/revoke`,{approvedBy:form.elements.approvedBy.value,reason:form.elements.reason.value}));});
