document.addEventListener('change',e=>{if(e.target.id==='open-family-select'){openFamily=e.target.value;render();}if(e.target.id==='family-filter'){familyFilter=e.target.value;render();}if(e.target.id==='research-family'){researchFamily=e.target.value;selectedEvidence.clear();render();}if(e.target.id==='production-family'){productionFamily=e.target.value;render();}if(e.target.classList.contains('brief-evidence')){if(e.target.checked)selectedEvidence.add(e.target.value);else selectedEvidence.delete(e.target.value);}if(e.target.id==='research-connector'){selectedConnector=e.target.value;channelResult=null;render();}});
async function researchAction(action){
  if(researchPending)return;
  researchPending=true;researchError='';channelResult=null;render();
  try{await action();await refresh();}catch(error){researchError=error.message;try{await refresh();}catch{}}
  finally{researchPending=false;render();}
}
document.addEventListener('submit',event=>{
  const form=event.target;
  if(form.id==='youtube-key-form'){
    event.preventDefault();const key=form.elements.key.value;form.elements.key.value='';
    researchAction(async()=>{await api('/api/youtube/key',{key});toast('Key saved with Windows protection. Look up a channel to test it.');});
  }
  if(form.id==='youtube-channel-form'){
    event.preventDefault();channelQuery=form.elements.channel.value;
    const id=form.elements.connector.value;
    researchAction(async()=>{if(id==='legacy')channelResult=await api('/api/youtube/channel',{channel:channelQuery});else{const c=state.connectors.find(x=>x.id===id);if(!c)throw new Error('Choose a saved YouTube connector.');channelResult=(await api(`/api/connectors/${id}/test`,{revision:c.revision,channel:channelQuery})).result;}});
  }
});
document.addEventListener('click',async event=>{
  const room=event.target.closest('[data-production-room]');if(room){productionRoom=room.dataset.productionRoom;render();return;}
  const styleFor=event.target.closest('[data-action="family-style"]');if(styleFor&&typeof familyStyleDialog==='function'){familyStyleDialog(styleFor.dataset.id);return;}
  const open=event.target.closest('[data-action="open-family"]')||(!event.target.closest('button,a,input,select,textarea,label,summary')&&event.target.closest('.family-card[data-family]'));if(open){openFamily=open.dataset.id||open.dataset.family;returnFamily='';location.hash='family';render();return;}
  const go=event.target.closest('[data-action="goto"],[data-action="family-go"]');if(go){const [where,familyId]=go.dataset.id.split('|'),[view,roomId]=where.split(':');if(go.dataset.action==='family-go')returnFamily=familyId;if(roomId){productionRoom=roomId;if(familyId)productionFamily=familyId;}if(familyId&&view==='competitors'&&typeof competitorFamily!=='undefined')competitorFamily=familyId;if(familyId&&view==='studio')familyFilter=familyId;if(familyId&&view==='family')openFamily=familyId;location.hash=view;render();return;}
  const close=event.target.closest('[data-close]');if(close){document.getElementById(close.dataset.close).close();return;}
  const remove=event.target.closest('[data-remove-source]');if(remove){remove.closest('.source-field').remove();return;}
  const button=event.target.closest('[data-action]');if(!button)return;
  const {action:command,id}=button.dataset;
  if(command.startsWith('style-'))return styleAction(command,id);
  if(command.startsWith('intel-')||command.startsWith('niche-')||command.startsWith('trend-'))return intelAction(command,id,button);
  if(command.startsWith('scene-'))return sceneAction(command,id,button);
  if(command.startsWith('render-'))return renderAction(command,id,button);
  if(command.startsWith('audio-'))return audioAction(command,id);
  if(command.startsWith('qc-'))return qcAction(command,id);
  if(command.startsWith('master-'))return masterAction(command,id);
  if(command.startsWith('edition-'))return editionAction(command,id);
  if(command.startsWith('pub-'))return publishAction(command,id);
  if(command.startsWith('pkg-'))return pkgAction(command,id,button);
  if(command.startsWith('vd-'))return vdAction(command,id,button);
  if(command.startsWith('tl-'))return editAction(command,id,button);
  if(command.startsWith('skill-'))return skillAction(command,id);
  if(command.startsWith('backup-'))return backupAction(command,id,button);
  if(command.startsWith('snd-'))return soundAction(command,id,button);
  if(command==='ops-days'){opsDays=Number(id)||14;return render();}
  if(command==='ops-refresh'){opsReport=null;return render();}
  if(command==='craft-pair'){const c=state.contents.find(item=>item.id===id),family=state.families.find(item=>item.id===c?.familyId),out=document.getElementById(`pair-${id}`);if(!c||!out)return;try{const result=await api('/api/craft/check',{title:c.title,thumbnailText:document.getElementById(`thumb-${id}`).value,locale:family?.primaryLocale||'en'});out.innerHTML=`<strong>Pairing · ${result.packaging.applicable?`${result.packaging.score}/100`:'length only'}</strong>${packagingList(result.packaging)}`;}catch(error){toast(error.message,true);}return;}
  if(command==='new-evidence'||command==='edit-evidence')return evidenceDialog(id);
  if(command==='archive-evidence'||command==='restore-evidence'){const item=state.researchEvidence.find(record=>record.id===id);button.disabled=true;try{await api(`/api/research/evidence/${id}/archive`,{revision:item.revision,archived:command==='archive-evidence'});selectedEvidence.delete(id);await refresh();toast('Research evidence updated.');}catch(error){toast(error.message,true);}finally{button.disabled=false;}return;}
  if(command==='prepare-research'){const family=state.families.find(item=>item.id===id),connector=readyClaudeConnection();if(!connector)return toast('Add and test a Claude connection first.',true);const evidence=[...selectedEvidence].map(evidenceId=>{const item=state.researchEvidence.find(record=>record.id===evidenceId);return {id:item.id,revision:item.revision};});if(!evidence.length)return toast('Select at least one eligible evidence record.',true);button.disabled=true;try{await api(`/api/families/${id}/research-briefs`,{familyRevision:family.revision,briefDate:localDay(family),connectorId:connector.id,connectorRevision:connector.revision,evidence});await refresh();toast('Daily research brief queued for review.');}catch(error){toast(error.message,true);}finally{button.disabled=false;}return;}
  if(command==='retry-research'){const job=state.researchJobs.find(item=>item.id===id),family=state.families.find(item=>item.id===job?.family_id),connector=readyClaudeConnection();if(!job||!family||!connector)return toast('Current research job, family, or Claude connection is unavailable.',true);const confirmInterrupted=job.status==='interrupted'||state.usage.some(item=>item.jobId===job.id&&item.status==='unknown');if(confirmInterrupted&&!confirm('This research request was interrupted, so provider spend is unknown. Deliberately retry it?'))return;button.disabled=true;try{await api(`/api/research-jobs/${id}/retry`,{familyRevision:family.revision,connectorId:connector.id,connectorRevision:connector.revision,confirmInterrupted});await refresh();toast('Research job deliberately requeued.');}catch(error){toast(error.message,true);}finally{button.disabled=false;}return;}
  if(command==='new-connector'||command==='edit-connector')return connectorDialog(id);
  if(command==='test-connector'||command==='delete-connector'){
    const c=state.connectors.find(x=>x.id===id);
    if(command==='delete-connector'&&!confirm(`Delete connector “${c.name}” and its saved local key? This does not revoke the provider key.`))return;
    if(command==='test-connector'){if(researchPending)return;c.busy=true;c.test={status:'testing',at:new Date().toISOString(),message:'Connector test in progress. Generation remains disabled until it passes.'};render();}
    return researchAction(async()=>{await api(`/api/connectors/${id}/${command==='test-connector'?'test':'delete'}`,{revision:c.revision});toast(command==='test-connector'?'Test finished. Read the result on the slot.':'Connector deleted.');});
  }
  if(command==='sign-in-connector'){const c=state.connectors.find(x=>x.id===id);return researchAction(async()=>{await api(`/api/connectors/${id}/sign-in`,{revision:c.revision});toast('ChatGPT\'s sign-in page opens in your browser. Sign in there, then come back.');});}
  if(command==='forget-key')return researchAction(async()=>{await api('/api/youtube/forget',{});toast('The local key was removed. Google Cloud revocation is separate.');});
  if(command==='new-family'||command==='edit-family')return familyDialog(id);
  if(command==='new-content'||command==='edit-content')return contentDialog(id);
  if(command==='use-claude-candidate'){
    const candidate=state.scriptCandidates.find(item=>item.id===id&&item.status==='available');if(!candidate)return toast('That Claude candidate did not pass the quality gate.',true);
    contentDialog(candidate.contentId);const form=$('#content-form');for(const field of ['title','angle','hook','script'])form.elements[field].value=candidate.payload[field];
    $('#revision-warning').textContent='Review this Claude candidate carefully. Saving creates a new draft revision and clears any previous approval or storyboard.';return;
  }
  if(command==='retry-claude'){
    const job=state.jobs.find(item=>item.id===id),c=state.contents.find(item=>item.id===job?.content_id),connector=readyClaudeConnection();
    if(!job||!c)return toast('That Claude job is no longer available.',true);
    if(!connector)return toast('Add and test a current Claude connection before retrying.',true);
    const confirmInterrupted=job.status==='interrupted'||state.usage.some(item=>item.jobId===job.id&&item.status==='unknown');
    if(confirmInterrupted&&!confirm('This request was interrupted, so its provider outcome and spend are unknown. Deliberately retry it anyway?'))return;
    button.disabled=true;try{await api(`/api/script-jobs/${job.id}/retry`,{revision:c.revision,connectorId:connector.id,connectorRevision:connector.revision,confirmInterrupted});await refresh();toast('Claude job deliberately requeued. Review the attempt count before any further retry.');}catch(e){toast(e.message,true);}finally{button.disabled=false;}return;
  }
  if(command==='configure-voice'){const family=state.families.find(item=>item.id===id);return family?voiceProfileDialog(family):toast('That family is no longer available.',true);}
  if(command==='approve-voice')return voiceApprovalDialog(id);
  if(command==='revoke-voice')return voiceRevokeDialog(id);
  if(command==='queue-voice'){
    const content=state.contents.find(item=>item.id===id),family=content&&state.families.find(item=>item.id===content.familyId),profile=family&&state.voiceProfiles.filter(item=>item.familyId===family.id).at(-1);
    if(!content||!family||!profile)return toast('A current approved script and narrator profile are required.',true);
    button.disabled=true;try{const direction=vdFor(content.id);await api(`/api/content/${content.id}/voice-auditions`,{contentRevision:content.revision,profileId:profile.id,profileRevision:profile.revision,connectorId:profile.connectorId,connectorRevision:profile.connectorRevision,...(direction?{directionId:direction.id}:{})});await refresh();toast('Voice audition admitted and queued. No automatic fallback will run.');}catch(error){toast(error.message,true);}finally{button.disabled=false;}return;
  }
  if(command==='retry-voice'){
    const job=state.voiceJobs.find(item=>item.id===id),profile=job&&state.voiceProfiles.find(item=>item.id===job.profile_id);
    if(!job||!profile)return toast('That voice job or immutable profile is no longer available.',true);
    const usage=state.voiceUsage.find(item=>item.jobId===job.id),confirmInterrupted=job.status==='interrupted'||usage?.status==='unknown';
    if(confirmInterrupted&&!confirm('This voice request ended with an unknown provider outcome, so it may already have cost money. Deliberately retry the exact same scope?'))return;
    button.disabled=true;try{await api(`/api/voice-jobs/${job.id}/retry`,{contentRevision:job.content_revision,profileId:job.profile_id,profileRevision:job.profile_revision,connectorId:job.connector_id,connectorRevision:job.connector_revision,confirmInterrupted});await refresh();toast('Exact voice scope deliberately requeued.');}catch(error){toast(error.message,true);}finally{button.disabled=false;}return;
  }
  if(command==='family-drafts'){familyFilter=id;location.hash='studio';render();return;}
  button.disabled=true;
  try{
    if(command==='delete-family-ask'){familyWork=(await api(`/api/families/${id}/work`,null,'GET')).work;familyDeleting=id;render();return;}
    if(command==='delete-family-cancel'){familyDeleting=null;render();return;}
    if(command==='family-saved-close'){familySaved=null;render();return;}
    if(command==='delete-family'){const f=state.families.find(f=>f.id===id);const keep=document.querySelector('input[name="delete-keep"]:checked')?.value!=='delete',result=await api(`/api/families/${id}/delete`,{revision:f.revision,confirmName:document.querySelector('[data-delete-name]')?.value||'',keep});familySaved=result.kept?result:null;familyDeleting=null;await refresh();toast(`${result.name} was deleted.`);return;}
    if(command==='archive-family'||command==='restore-family'){const f=state.families.find(f=>f.id===id);await api(`/api/families/${id}/archive`,{revision:f.revision,archived:command==='archive-family'});}
    else {const c=state.contents.find(c=>c.id===id);if(command==='storyboard')await api(`/api/content/${id}/storyboard`,{revision:c.revision});else if(command==='ai-script'){const connector=readyClaudeConnection();if(!connector)throw new Error('Add and test a Claude connection first.');await api(`/api/content/${id}/ai-script`,{revision:c.revision,connectorId:connector.id,connectorRevision:connector.revision});}else await api(`/api/content/${id}/review`,{revision:c.revision,action:command.split('-')[0]});}
    await refresh();toast(command==='storyboard'?'Storyboard planning job queued.':command==='ai-script'?'Claude script job queued. The candidate will require review.':'Workspace updated.');
  }catch(e){toast(e.message,true);}finally{button.disabled=false;}
});
window.addEventListener('hashchange',render);
function setupSkipped(){try{return sessionStorage.getItem('claudeSetupSkipped')==='1';}catch{return false;}}
function setupMode(){const form=$('#setup-form'),mode=form.elements.mode.value;form.querySelector('[data-setup-key]').hidden=mode!=='claude';form.elements.key.required=mode==='claude';form.querySelectorAll('[data-setup-model]').forEach(field=>{field.hidden=mode==='chatgpt';});}
function openSetupIfNeeded(){if(!state||state.connectors.some(connector=>AI_PROVIDERS.includes(connector.provider))||setupSkipped()||$('#setup-dialog').open)return;const form=$('#setup-form');form.reset();form.querySelector('.form-error').hidden=true;modelOptions(form.elements.mainModel,state.ai.defaults.main);modelOptions(form.elements.supportModel,state.ai.defaults.support);form.querySelector('[data-claude-code-status]').textContent=state.ai.claudeCodeFound?'Claude Code was found on this PC.':'Claude Code was not found on this PC: install it and log in, or use an API key.';form.querySelector('[data-codex-status]').textContent=state.ai.codexFound?'The Codex app was found on this PC.':'The Codex app was not found on this PC: install it from the Microsoft Store and sign in with ChatGPT.';if(!state.ai.claudeCodeFound)form.elements.mode.value='claude';setupMode();$('#setup-dialog').showModal();}
$('#setup-form').addEventListener('change',event=>{if(event.target.name==='mode')setupMode();});
$('#setup-form').querySelector('[data-setup-skip]').addEventListener('click',()=>{try{sessionStorage.setItem('claudeSetupSkipped','1');}catch{}$('#setup-dialog').close();toast('Setup skipped. AI jobs stay off until a Claude or ChatGPT connection passes its test (Connections).');});
$('#setup-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,mode=form.elements.mode.value,error=form.querySelector('.form-error'),result=form.querySelector('[data-setup-result]'),submit=form.querySelector('[type=submit]');error.hidden=true;submit.disabled=true;result.textContent='Saving the connection and testing it…';
  try{const name={claude:'Claude API key','claude-code':'Claude subscription',chatgpt:'ChatGPT subscription'}[mode];let connector=state.connectors.find(item=>item.provider===mode&&item.name===name);const body={name,provider:mode,notes:'Created by the setup screen.',models:mode==='chatgpt'?{main:''}:{main:form.elements.mainModel.value,support:form.elements.supportModel.value},...(mode==='claude'?{key:form.elements.key.value}:{})};
    connector=connector?await api(`/api/connectors/${connector.id}`,{...body,revision:connector.revision},'PUT'):await api('/api/connectors',body);form.elements.key.value='';
    const tested=await api(`/api/connectors/${connector.id}/test`,{revision:connector.revision});await refresh();$('#setup-dialog').close();toast(tested.result?.message||'The AI is connected.');}
  catch(e){error.textContent=`${e.message} The connection was kept; you can fix it and test again here or in Connections.`;error.hidden=false;result.textContent='';await refresh().catch(()=>{});}
  finally{submit.disabled=false;}});
// Says at once when the program stops (before a form is filled in) and reloads the workspace when it is back.
let programOffline=false;
setInterval(async()=>{let up=false;try{up=(await fetch('/api/health',{cache:'no-store'})).ok;}catch{}if(up!==programOffline)return;programOffline=!up;$('#offline-banner').hidden=up;if(up)refresh().catch(()=>{});},4000);
refresh().then(openSetupIfNeeded).catch(e=>{$('#main').textContent=e.message;toast(e.message,true);});
setInterval(()=>{const audioPlaying=[...document.querySelectorAll('audio,video')].some(audio=>!audio.paused&&!audio.ended);if(!audioPlaying&&(state?.jobs.some(j=>['queued','running'].includes(j.status))||state?.researchJobs.some(j=>['queued','running'].includes(j.status))||state?.voiceJobs.some(j=>['queued','running'].includes(j.status))||(typeof intelBusy==='function'&&intelBusy())||(typeof sceneBusy==='function'&&sceneBusy())||(typeof renderBusy==='function'&&renderBusy())||state?.frameScans?.active>0||state?.soundtrack?.sounds?.imports?.some(item=>['queued','running'].includes(item.status))||state?.packaging?.busy||state?.localization?.busy||state?.publishing?.busy)&&!document.querySelector('dialog[open]')&&!document.activeElement?.closest?.('[data-tl-root]')&&location.hash!=='#connections')refresh().catch(()=>{});},1500);
